package ru.neverland.townyenvironment;
import java.util.*;
import java.math.BigDecimal;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;
import ru.neverland.core.SuiteState;
import ru.neverland.townyenvironment.model.DistrictEnvironment;
import ru.neverland.townyenvironment.integration.DistrictEnvironmentBridge;
import ru.neverland.townyenvironment.service.DistrictEnvironmentViews;
import static ru.neverland.townyenvironment.model.DistrictEnvironment.*;
public final class DistrictEnvironmentSmoke {
    static int checks;static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}interface Work{void run()throws Exception;}static void denied(Work work,String why)throws Exception{try{work.run();}catch(Exception expected){check(true,why);return;}throw new AssertionError(why);}
    static BigDecimal n(String s){return new BigDecimal(s);}@SuppressWarnings("unchecked")static Map<String,Object> map(Object value){return(Map<String,Object>)value;}
    static Input input(){return new Input(n("0.6000000000000001"),n("1.2"),Map.of(NATURE,new Source(NATURE,"Природа",0,BigDecimal.ZERO,n(".2")),"forge",new Source("forge","Кузница",5,n(".6"),BigDecimal.ZERO),"park",new Source("park","Парк",5,BigDecimal.ZERO,n("1"))),Map.of("industry",new District("industry","Мастерские"),"homes",new District("homes","Жилой квартал")),Map.of("forge","industry","park","homes"));}
    static void exact(Map<String,Object> result){var totals=map(result.get("totals"));for(String key:List.of("emissions","cleaning","change")){var total=BigDecimal.ZERO;for(var row:map(result.get("rows")).values())total=total.add(n((String)map(row).get(key)));if(total.compareTo(n((String)totals.get(key)))!=0)throw new AssertionError("sum differs: "+key);}for(var row:map(result.get("rows")).values())for(String key:List.of("emissions","cleaning")){var total=BigDecimal.ZERO;for(var source:map(map(row).get("sources")).values())total=total.add(n((String)map(source).get(key)));if(total.compareTo(n((String)map(row).get(key)))!=0)throw new AssertionError("source sum differs");}}
    static Map<String,Object> validReport(){return Map.of("available",true,"pending",false,"format",2,"sourceAt",1000L,"checkedAt",1001L,"rows",Map.of("homes",Map.of("id","homes","name","Жилой квартал","buildingsAvailable",true,"worldAvailable",true)),"assignments",Map.of("park","homes"));}
    public static void main(String[] args)throws Exception{
        var input=input();var result=DistrictEnvironment.calculate(input);exact(result);check(map(result.get("rows")).size()==3,"city and two actual districts");var city=map(map(result.get("rows")).get("city"));check(map(city.get("sources")).containsKey(NATURE)&&city.get("greenBuildings").equals(0),"nature belongs to city and is not a constructed green building");var home=map(map(result.get("rows")).get("district:homes"));check(home.get("greenBuildings").equals(1)&&n((String)home.get("cleaning")).signum()>0,"park is explicit cleaning source in its physical district");check(n((String)map(result.get("totals")).get("emissions")).equals(input.emissions()),"engine total including floating point accumulation retained exactly");
        denied(()->map(result.get("rows")).clear(),"immutable rows");denied(()->map(home.get("sources")).clear(),"immutable nested sources");denied(()->new Input(n("1"),n("1"),input.sources(),input.districts(),Map.of("park","missing")),"unrecognized district assignment refused");denied(()->DistrictEnvironment.calculate(new Input(n("2"),input.cleaning(),input.sources(),input.districts(),input.assignments())),"unexplained pressure difference refused");
        var random=new Random(9151);for(int trial=0;trial<10000;trial++){var sources=new LinkedHashMap<String,Source>();sources.put(NATURE,new Source(NATURE,"Nature",0,BigDecimal.ZERO,n(".2")));var assignments=new HashMap<String,String>();double emissions=0,cleaning=.2;for(int i=0;i<1+random.nextInt(30);i++){double e=random.nextInt(100)*.01,c=random.nextInt(100)*.01;emissions+=e;cleaning+=c;String id="source_"+i;sources.put(id,new Source(id,id,1,BigDecimal.valueOf(e),BigDecimal.valueOf(c)));if(random.nextBoolean())assignments.put(id,random.nextBoolean()?"homes":"industry");}var data=new Input(BigDecimal.valueOf(emissions),BigDecimal.valueOf(cleaning),sources,input.districts(),assignments);exact(DistrictEnvironment.calculate(data));var reversed=new LinkedHashMap<String,Source>();var keys=new ArrayList<>(sources.keySet());Collections.reverse(keys);keys.forEach(k->reversed.put(k,sources.get(k)));if(!DistrictEnvironment.calculate(data).equals(DistrictEnvironment.calculate(new Input(data.emissions(),data.cleaning(),reversed,data.districts(),data.assignments()))))throw new AssertionError("iteration order changes report");}check(true,"10000 exact allocations and ordering invariance");
        var parsed=DistrictEnvironmentBridge.decode(validReport(),2000);check(parsed.available()&&parsed.assignments().get("park").equals("homes"),"format2 physical map parsed");check(!DistrictEnvironmentBridge.decode(validReport(),62000).available(),"old source not reused as fresh");var bad=new HashMap<>(validReport());bad.put("format",1);denied(()->DistrictEnvironmentBridge.decode(bad,2000),"old format refused");var unavailable=Map.of("available",false,"pending",false);check(!DistrictEnvironmentBridge.decode(unavailable,2000).available(),"unavailable report never becomes empty districts");bad.put("format",2);bad.put("assignments",Map.of("park","other"));denied(()->DistrictEnvironmentBridge.decode(bad,2000),"cross-contract dangling assignment refused");
        var clock=new AtomicLong();var views=new DistrictEnvironmentViews(clock::get,error->{throw new AssertionError(error);});UUID id=UUID.randomUUID();check(Boolean.TRUE.equals(views.read(id).get("pending")),"async interest registers without source capture");for(int i=0;i<100&&!Boolean.TRUE.equals(views.read(id).get("available"));i++){views.capture(id,input,1000,false);Thread.sleep(2);}check(Boolean.TRUE.equals(views.read(id).get("available")),"bounded worker computes detached input");try(var held=SuiteState.guard()){var read=CompletableFuture.supplyAsync(()->views.read(id));check(read.get(1,TimeUnit.SECONDS).get("available").equals(true),"async reads never wait for shared suite lock");}var changed=new Input(input.emissions(),input.cleaning(),input.sources(),input.districts(),Map.of());views.capture(id,changed,2000,false);check(Boolean.TRUE.equals(views.read(id).get("pending")),"changed assignment invalidates previous ready report");for(int i=0;i<200;i++)views.watch(UUID.randomUUID());check(views.wanted().size()==128,"bounded interest");clock.set(121_000_000_000L);check(views.wanted().isEmpty(),"idle interest expires");views.prepareClose().toCompletableFuture().get(3,TimeUnit.SECONDS);check(Boolean.FALSE.equals(views.read(id).get("available")),"shutdown closes derived view only");
        System.out.println("DistrictEnvironmentSmoke PASS "+checks+" checks plus 10000 conserved allocations");
    }
}
